sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
uniform float blur;
uniform float nearDist;
uniform float farDist;
uniform float angle;
layout(color) uniform half4 shadowColor;
uniform float nearOpacity;
uniform float farOpacity;
uniform float shadowOnly;
uniform float opacity;
float4 texT(float2 p) {
    return float4(image.eval(p));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = texT(coord);
    float2 d = float2(cos(radians(angle)), sin(radians(angle)));
    float near = texT(coord - d * nearDist).a;
    float far = float4(blurred.eval(clamp(coord - d * farDist, float2(0.0), size))).a;
    float sa = saturate(near * nearOpacity + far * farOpacity * (1.0 - near * nearOpacity));
    float4 shadow = float4(float3(shadowColor.rgb) * sa, sa);
    float4 r = shadowOnly > 0.5 ? shadow : c + shadow * (1.0 - c.a);
    return fin(c, r, opacity);
}
